def test_darija_arabic_messages_are_curated_and_script_valid() -> None:
    assert DARIJA_ARABIC_MESSAGES == EXPECTED_DARIJA_ARABIC_MESSAGES
    for message in DARIJA_ARABIC_MESSAGES.values():
        assert validate_localized_script(message, "ary", "arabic")
        assert not any(marker in message for marker in ("\u00c3", "\u00c2", "\u00d9", "\u00d8", "\ufffd"))


def test_msa_and_other_localization_tables_remain_distinct() -> None:
    assert MESSAGES["ar"]["pedagogie"] == (
        "\u064a\u0645\u0643\u0646\u0646\u064a \u0634\u0631\u062d \u0627\u0644\u0623\u0633\u0647\u0645 \u0648\u0627\u0644\u0633\u0646\u062f\u0627\u062a \u0648\u0627\u0644\u0645\u0624\u0634\u0631\u0627\u062a \u0648\u0627\u0644\u0645\u062e\u0627\u0637\u0631 \u0644\u0623\u063a\u0631\u0627\u0636 \u062a\u0639\u0644\u064a\u0645\u064a\u0629."
    )
    assert localize_answer("source", "fr", "latin", route="pedagogie") == "source"
    assert localize_answer("source", "en", "latin", route="pedagogie") == "source"
    assert localize_answer("source", "ary", "latin", route="pedagogie") == "source"
